// What a JSX compiler produces: <div className="x">Hi</div> becomes a function call
// that returns a plain object (an element). No browser support is needed.
function jsx(type, props) {
  return { type: type, props: props };
}

// Tiny renderer: turns elements into an HTML string, escaping text like React does.
function esc(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
function render(el) {
  if (typeof el === "string" || typeof el === "number") return esc(el);
  if (typeof el.type === "function") return render(el.type(el.props)); // component
  const attrs = Object.keys(el.props)
    .filter(k => k !== "children")
    .map(k => " " + (k === "className" ? "class" : k) + '="' + esc(el.props[k]) + '"')
    .join("");
  const kids = [].concat(el.props.children === undefined ? [] : el.props.children);
  return "<" + el.type + attrs + ">" + kids.map(render).join("") + "</" + el.type + ">";
}

function Greeting(props) {
  return jsx("div", { className: "x", children: "Hi " + props.name });
}
const el = jsx(Greeting, { name: "<b>Asha</b>" }); // what <Greeting name=... /> compiles to
console.log("element:", JSON.stringify({ type: "Greeting", props: el.props }));
console.log("html:", render(el)); // the user text is escaped, so it is not XSS

// Each row keeps its own typed text (state). We delete the first item and
// match old rows to new rows either by index or by id (the key).
function reconcile(oldRows, newItems, keyOf) {
  return newItems.map((item, i) => {
    const match = oldRows.find((r, j) => keyOf(r.item, j) === keyOf(item, i));
    return { item: item, text: match ? match.text : "" }; // reuse state if matched
  });
}
const items = [{ id: 1, name: "Ann" }, { id: 2, name: "Bob" }, { id: 3, name: "Cy" }];
const typed = ["note for Ann", "", ""]; // user typed only in the first row
const rows = items.map((item, i) => ({ item: item, text: typed[i] }));
const after = items.slice(1); // delete Ann
const show = rs => rs.map(r => r.item.name + ":[" + r.text + "]").join(" ");

console.log("before:      ", show(rows));
console.log("key = index: ", show(reconcile(rows, after, (it, i) => i)));
console.log("key = id:    ", show(reconcile(rows, after, it => it.id)));
// With index keys Bob inherits Ann's note. With id keys the note disappears with Ann.

// Simulates React's state snapshot and update queue for one click handler.
function click(handler) {
  let state = 0, queue = [];
  const setCount = v => queue.push(v);   // setters only queue; they do not change count now
  handler(state, setCount);              // handler sees the snapshot: state = 0
  for (const u of queue) state = typeof u === "function" ? u(state) : u;
  return state;                          // one render with the final value
}
const bad = click((count, setCount) => {
  setCount(count + 1); setCount(count + 1); setCount(count + 1); // queues 1, 1, 1
});
const good = click((count, setCount) => {
  setCount(c => c + 1); setCount(c => c + 1); setCount(c => c + 1); // 0->1->2->3
});
console.log("start count = 0");
console.log("setCount(count + 1) x3  ->", bad);
console.log("setCount(c => c + 1) x3 ->", good);

// React checks "did state change?" with Object.is, a reference comparison for arrays.
function setState(oldValue, newValue) {
  return Object.is(oldValue, newValue) ? "same reference -> skip re-render" : "new reference -> re-render";
}
let items = ["a", "b"];
const before = items;

items.push("c");                         // mutation: same array object
console.log("mutated:", JSON.stringify(items), "|", setState(before, items));

const next = [...items, "d"];            // copy: a new array object
console.log("copied: ", JSON.stringify(next), "|", setState(items, next));

const snapshot = items;                  // a closure holding an old snapshot
items.push("e");
console.log("old snapshot changed under us:", JSON.stringify(snapshot));
const safe = next.map(x => x);           // map / filter / spread always return new arrays
console.log("map gives new array:", safe !== next);

// Mimics what React prints for a child value: numbers and strings show, the rest is empty.
function renderChild(v) {
  if (v === false || v === null || v === undefined || v === true) return "(nothing)";
  return '"' + String(v) + '"';   // numbers, including 0 and NaN, are rendered as text
}
const Badge = "<Badge/>";
for (const count of [0, 3]) {
  console.log("count =", count);
  console.log("  count && Badge       ->", renderChild(count && Badge));        // bug at 0
  console.log("  count > 0 && Badge   ->", renderChild(count > 0 && Badge));    // fix 1
  console.log("  count ? Badge : null ->", renderChild(count ? Badge : null));  // fix 2
}
console.log("NaN && Badge ->", renderChild(NaN && Badge)); // NaN renders too

// State lives in a slot identified by (position, type, key). Same identity keeps state.
const slots = {};                         // identity -> state
function mount(position, type, key, name) {
  const id = position + "|" + type + "|" + (key === undefined ? "" : key);
  const fresh = !(id in slots);
  if (fresh) slots[id] = { text: "" };    // new identity: new state
  return { id: id, state: slots[id], fresh: fresh, name: name };
}
let a = mount("root", "Chat", undefined, "Me");
a.state.text = "hello Me";                // the user types something
let b = mount("root", "Chat", undefined, "Ben");  // same type, position, key
console.log("same type + position:", b.fresh ? "reset" : "kept", JSON.stringify(b.state));
let c = mount("root", "Chat", "ben", "Ben");      // key added
console.log("new key:             ", c.fresh ? "reset" : "kept", JSON.stringify(c.state));
let d = mount("root", "Other", undefined, "Ben"); // different type
console.log("different type:      ", d.fresh ? "reset" : "kept", JSON.stringify(d.state));
